/**
 * 从响应头 Content-Disposition 解析真实文件名（兼容 filename 与 filename*=UTF-8'' 形式）。
 * 后端多以 attachment;filename=xxx.docx / filename*=UTF-8''xxx.docx 返回，
 * 该文件名自带正确扩展名，是下载文件后缀的权威来源，可避免“下载后变成 .txt”之类问题。
 */
function extractFilenameFromDisposition(contentDisposition) {
  if (!contentDisposition) return ''
  let decoded = contentDisposition
  try {
    decoded = decodeURIComponent(contentDisposition)
  } catch (e) {
    // 含非法 % 序列时退回原始串
  }
  const starMatch = /filename\*\s*=\s*[^']*''([^;]+)/i.exec(decoded)
  if (starMatch && starMatch[1]) {
    return starMatch[1].replace(/^["']|["']$/g, '').trim()
  }
  const match = /filename\s*=\s*"?([^";]+)"?/i.exec(decoded)
  if (match && match[1]) {
    return match[1].trim()
  }
  return ''
}

/** 文件名是否带扩展名 */
function hasFileExtension(name) {
  return typeof name === 'string' && /\.[a-z0-9]{1,12}$/i.test(name.trim())
}

/**
 * 决定最终下载文件名：调用方传入的文件名若已带扩展名则优先（避免覆盖业务自定义名，
 * 如“用户导入模板.xlsx”）；否则回退到响应头 Content-Disposition 里的真实文件名；
 * 都没有扩展名时退回原始名（真实扩展名仍可能由服务端 Content-Disposition 决定）。
 */
function resolveDownloadName(filename, contentDisposition) {
  if (hasFileExtension(filename)) return filename.trim()
  const realName = extractFilenameFromDisposition(contentDisposition)
  if (hasFileExtension(realName)) return realName
  return filename
}

function saveBlobToFile(data, filename) {
  // data 可能是裸 Blob，也可能是携带 headers 的响应对象（downloadGet 走 returnRawResponse）
  let blob = data
  let contentDisposition
  if (data && data.data instanceof Blob) {
    blob = data.data
    contentDisposition = data.headers && data.headers['content-disposition']
  }
  if (!blob || blob.size < 100) {
    throw new Error('下载失败')
  }
  const finalName = resolveDownloadName(filename, contentDisposition)
  // 保留服务端返回的真实 MIME 类型，避免 Blob 重建时类型丢失导致浏览器误判后缀（如变成 .txt）
  const outBlob = new Blob([blob], { type: blob.type || 'application/octet-stream' })
  if ('download' in document.createElement('a')) {
    const elink = document.createElement('a')
    elink.download = finalName
    elink.style.display = 'none'
    elink.href = URL.createObjectURL(outBlob)
    document.body.appendChild(elink)
    elink.click()
    URL.revokeObjectURL(elink.href)
    document.body.removeChild(elink)
  } else {
    navigator.msSaveBlob(outBlob, finalName)
  }
  return data
}
